"""Scoped, reversible identity encoding; no evidence or policy pruning."""

from __future__ import annotations

import json
import re

WIRE_VERSION = "semantic-compact-v4"
_HEX = re.compile(r"[0-9a-f]{16,64}\Z")
_ALIAS = re.compile(r"(?:r[0-9]+|s)_[ief][0-9]+\Z")
_LITERAL_HEX = re.compile(r"\b[0-9a-f]{7,64}\b", re.IGNORECASE)


def _reference(key):
    # Role/step labels are generated by the model, not references to input IDs.
    # Their unrestricted domain may legitimately overlap the alias namespace.
    if key in {"role_id", "step_id"}:
        return False
    return key.endswith(("_id", "_ids")) or key == "sha"


class CandidateAliases:
    def __init__(self, key, context, shared_literal_ids=(), shared_ids=None):
        self.key, self.encode_ids = key, {}
        self.shared_ids = shared_ids or {}
        # A literal hash in a message/body/path carries a visible reference.
        # Keep matching identities literal too, including abbreviated commit
        # hashes, rather than breaking that relation for the model.
        self.literal_ids = set()
        self._collect_literals(context)
        # Visible hashes and envelope identities stay literal. Shared spellings
        # never expand a candidate's own Evidence/fact authorization domain.
        self.literal_ids.update(shared_literal_ids)
        from skillforge.repository.semantic_reference_schema import reference_domains

        domains = reference_domains(context)
        self.evidence_ids = set(domains["evidence"])
        self.fact_ids = set(domains["facts"])
        self.encode(context)
        self.decode_ids = {value: original for original, value in self.encode_ids.items()}

    def _collect_literals(self, value, key=""):
        if isinstance(value, dict):
            for name, item in value.items():
                self.literal_ids.update(s.lower() for s in _LITERAL_HEX.findall(name))
                self._collect_literals(item, name)
        elif isinstance(value, list):
            for item in value:
                self._collect_literals(item, key)
        elif isinstance(value, str) and not _reference(key):
            self.literal_ids.update(s.lower() for s in _LITERAL_HEX.findall(value))

    def encode(self, value, key=""):
        if isinstance(value, dict):
            return {name: self.encode(item, name) for name, item in value.items()}
        if isinstance(value, list):
            return [self.encode(item, key) for item in value]
        if isinstance(value, str) and _reference(key) and _HEX.fullmatch(value):
            if any(value.startswith(literal) for literal in self.literal_ids):
                return value
            if value not in self.encode_ids:
                kind = "e" if value in self.evidence_ids else "f" if value in self.fact_ids else "i"
                self.encode_ids[value] = self.shared_ids.get(
                    value, f"{self.key}_{kind}{len(self.encode_ids)}"
                )
                if hasattr(self, "decode_ids"):
                    self.decode_ids[self.encode_ids[value]] = value
            return self.encode_ids[value]
        return value

    def decode(self, value, key=""):
        if isinstance(value, dict):
            return {name: self.decode(item, name) for name, item in value.items()}
        if isinstance(value, list):
            return [self.decode(item, key) for item in value]
        if isinstance(value, str) and _reference(key) and _ALIAS.fullmatch(value):
            if value not in self.decode_ids:
                raise ValueError("unknown or foreign candidate identity alias")
            return self.decode_ids[value]
        return value


class CompactBatch:
    """Share exact policies/schemas, keep every context under a separate candidate."""

    def __init__(self, entries, response_schemas, *, share_context=True):
        self.originals, self.aliases, policies, schemas, candidates = {}, {}, {}, {}, []
        self.original_prompts = {}
        from collections import Counter

        contexts = []
        for entry in entries:
            contexts.append(
                json.loads(entry["original_prompt"].partition("\nCANDIDATE_CONTEXT:\n")[2])
            )
        references = Counter()

        def collect(value, found, name=""):
            if isinstance(value, dict):
                for field, child in value.items():
                    collect(child, found, field)
            elif isinstance(value, list):
                for child in value:
                    collect(child, found, name)
            elif isinstance(value, str) and _reference(name) and _HEX.fullmatch(value):
                found.add(value)

        for context in contexts:
            found = set()
            collect(context, found)
            references.update(found)
        from skillforge.repository.semantic_reference_schema import reference_domains

        shared_literal_ids = {
            entry[field] for entry in entries for field in ("repository_id", "candidate_id")
        }
        literal_ids, evidence_ids, fact_ids = set(), set(), set()
        for i, context in enumerate(contexts):
            local = CandidateAliases(f"r{i}", context)
            literal_ids.update(local.literal_ids)
            domains = reference_domains(context)
            evidence_ids.update(domains["evidence"])
            fact_ids.update(domains["facts"])
        if evidence_ids & fact_ids:
            raise ValueError("ambiguous shared Evidence/fact identity")
        shared_ids = {}
        for value in sorted(value for value, count in references.items() if count > 1):
            if value in shared_literal_ids or any(
                value.startswith(literal) for literal in literal_ids
            ):
                shared_literal_ids.add(value)
                continue
            kind = "e" if value in evidence_ids else "f" if value in fact_ids else "i"
            shared_ids[value] = f"s_{kind}{len(shared_ids)}"
        if not share_context:
            shared_literal_ids, shared_ids = set(), {}
        for i, (entry, response_schema) in enumerate(zip(entries, response_schemas, strict=True)):
            key = f"r{i}"
            policy, marker, rest = entry["original_prompt"].partition("\nRESPONSE_SCHEMA:\n")
            schema_text, context_marker, context_text = rest.partition("\nCANDIDATE_CONTEXT:\n")
            if not marker or not context_marker or json.loads(schema_text) != response_schema:
                raise ValueError("unrecognized compact prompt contract")
            context = json.loads(context_text)
            aliases = CandidateAliases(key, context, shared_literal_ids, shared_ids)
            # Identity maps and raw prompts remain local; nothing is summarized.
            self.originals[key] = {k: v for k, v in entry.items() if k != "original_prompt"}
            self.original_prompts[key] = entry["original_prompt"]
            self.aliases[key] = aliases
            policy_key = next((k for k, v in policies.items() if v == policy), f"p{len(policies)}")
            schema_key = next(
                (k for k, v in schemas.items() if v == response_schema), f"s{len(schemas)}"
            )
            policies[policy_key] = policy
            schemas[schema_key] = response_schema
            candidates.append(
                {
                    "request_id": key,
                    "repository_id": aliases.encode(entry["repository_id"], "repository_id"),
                    "candidate_id": aliases.encode(entry["candidate_id"], "candidate_id"),
                    "policy": policy_key,
                    "response_schema": schema_key,
                    "CANDIDATE_CONTEXT": aliases.encode(context),
                }
            )
        self.candidates, self.policies, self.response_schemas = candidates, policies, schemas
        from skillforge.repository.semantic_reference_schema import (
            bind_response_schema,
            reference_domains,
        )

        envelopes = {}
        definitions = {}
        bindings = {}
        for entry in candidates:
            key = entry["request_id"]
            context = entry["CANDIDATE_CONTEXT"]
            bindings[key] = reference_domains(context)
            # Aliases conceal the original ID spelling. Publish its canonical
            # order so a model can satisfy sorted-ID gates without hidden ranks.
            original_context = contexts[int(key[1:])]
            bindings[key]["evidence"] = [self.aliases[key].encode(value, "evidence_id")
                                        for value in reference_domains(original_context)["evidence"]]
            bound = bind_response_schema(
                schemas[entry["response_schema"]], context, definition_prefix=key + "_"
            )
            definitions.update(bound.pop("$defs", {}))
            definitions[key + "_response"] = bound
            properties = {
                k: {"type": "string", "enum": [entry[k]]}
                for k in ("request_id", "repository_id", "candidate_id")
            }
            properties.update(
                response={"anyOf": [{"$ref": f"#/$defs/{key}_response"}, {"type": "null"}]},
                error={"type": ["string", "null"]},
            )
            envelopes[entry["request_id"]] = {
                "type": "object",
                "additionalProperties": False,
                "required": list(properties),
                "properties": properties,
            }
        self.schema = {
            "type": "object",
            "additionalProperties": False,
            "required": ["results"],
            "properties": {
                "results": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": list(envelopes),
                    "properties": envelopes,
                }
            },
            "$defs": definitions,
        }
        from skillforge.repository.semantic_context_catalog import ExactContextCatalog

        contexts = [entry["CANDIDATE_CONTEXT"] for entry in candidates]
        catalog = ExactContextCatalog(contexts if share_context else [])
        self.shared_context = catalog.blocks
        self.wire_candidates = [
            {**entry, "CANDIDATE_CONTEXT": context}
            for entry, context in zip(
                candidates, catalog.contexts if share_context else contexts, strict=True
            )
        ]
        shared_instruction = (
            (
                "In CANDIDATE_CONTEXT, an object containing only $skillforge_context means "
                "the exact value in EXACT_SHARED_CONTEXT under that key. Substitute that value "
                "in place before evaluation, recursively expanding block references. "
                "Shared storage "
                "does not grant access to unreferenced blocks or another candidate's evidence. "
            )
            if self.shared_context
            else ""
        )
        payload = {
            "POLICIES": policies,
            "RESPONSE_SCHEMAS": schemas,
            "REFERENCE_BINDINGS": bindings,
            "candidates": self.wire_candidates,
        }
        if self.shared_context:
            payload["EXACT_SHARED_CONTEXT"] = self.shared_context
        alias_instruction = (
            "Opaque identity aliases are authorized only within each candidate's own reference "
            "domains, even when the same alias occurs in multiple contexts. "
            if self.shared_context
            else "Opaque identity aliases are local to that candidate. "
        )
        self.prompt = (
            WIRE_VERSION + ": Evaluate every candidate independently. Apply its referenced POLICY "
            "verbatim and its referenced RESPONSE_SCHEMA to only its CANDIDATE_CONTEXT. "
            "Never use another candidate context or evidence. "
            + alias_instruction
            + "Only its REFERENCE_BINDINGS.evidence IDs may appear in "
            "Evidence fields; REFERENCE_BINDINGS.facts IDs belong only in supporting_fact_ids. "
            "Candidate, pattern and commit identities are not Evidence. "
            "For sorted Evidence fields, retain the listed REFERENCE_BINDINGS.evidence order "
            "when selecting a subset; that list follows original canonical ID order. "
            "Paths, modules, source bodies, messages and semantic criteria are unchanged. "
            + shared_instruction
            + "Return one results object keyed by each request_id; every key is required. "
            "Each envelope copies request_id/repository_id/candidate_id and contains response "
            "matching its schema and error=null; on candidate failure use response=null and "
            "a string error. Do not use tools.\nSEMANTIC_COMPACT:\n"
            + json.dumps(
                payload,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            )
        )
        if share_context:
            unshared = CompactBatch(entries, response_schemas, share_context=False)

            def size(batch):
                return len(batch.prompt.encode("utf-8")) + len(
                    json.dumps(batch.schema, ensure_ascii=False).encode("utf-8")
                )

            if size(self) >= size(unshared):
                self.__dict__.update(unshared.__dict__)

    def decode_item(self, item):
        if not isinstance(item, dict):
            return item
        key = item.get("request_id")
        if key not in self.originals:
            return item
        expected = next(c for c in self.candidates if c["request_id"] == key)
        if any(item.get(k) != expected[k] for k in ("repository_id", "candidate_id")):
            # Never turn a mismatched envelope into a valid binding.
            return item
        original = self.originals[key]
        result = {**item, **original}
        result["response"] = self.aliases[key].decode(item.get("response"))
        return result

    def normalize(self, raw):
        if not isinstance(raw, dict) or set(raw) != {"results"}:
            return raw, {}
        results = raw["results"]
        if isinstance(results, dict):
            items = [
                v for k, v in results.items() if isinstance(v, dict) and v.get("request_id") == k
            ]
        elif isinstance(results, list):
            items = results
        else:
            return raw, {}
        decoded, failures = [], {}
        for item in items:
            try:
                decoded.append(self.decode_item(item))
            except ValueError as exc:
                key = item["request_id"]
                failures[self.originals[key]["request_id"]] = (str(exc), item.get("response"))
                # Keep a deliberately unparseable response in the normal identity
                # path so duplicate-envelope detection still precedes isolation.
                decoded.append({**item, **self.originals[key], "response": {}})
        return {"results": decoded}, failures


def compact_enabled(model):
    import subprocess

    if model._runner is subprocess.run:
        return True
    parameters = getattr(model, "semantic_cache_identity", {}).get("response_parameters", {})
    return parameters.get("semantic_wire") == WIRE_VERSION
